import { error } from "@sveltejs/kit";

export async function api<T>(fetch: typeof globalThis.fetch, path: string) {
  const res = await fetch(path);
  if (!res.ok) throw error(res.status, "Request Failed");
  return res.json() as Promise<T>;
}

export function errorResponse(
  status: number,
  code: string,
  message: string,
  fields?: Record<string, unknown>,
): Response {
  const error = {
    code: code,
    message: message,
    fields: fields,
  };

  return Response.json({ error: error }, { status: status });
}
